"use strict";

function chapter(factionId, number, spec, climax = false) {
  const entry = {
    id: `${factionId}-${spec.slug}`,
    playableName: spec.hero,
    opponentName: spec.foe,
    title: spec.title,
    story: spec.story,
    dialogue: [
      `Narrator: ${spec.before}`,
      `${spec.hero}: ${spec.heroLine}`,
      `${spec.foe}: ${spec.foeLine}`,
      `${spec.ally}: ${spec.allyLine}`,
      `${spec.hero}: ${spec.answer}`
    ],
    endDialogue: [
      `Narrator: ${spec.after}`,
      `${spec.foe}: ${spec.foeAfter}`,
      `${spec.ally}: ${spec.allyAfter}`,
      `${spec.hero}: ${spec.finalLine}`,
      `Narrator: Chapter ${number} closes, but its choice changes every battle that follows.`
    ]
  };
  if (spec.sceneStarter) entry.sceneStarter = { ...spec.sceneStarter };
  if (factionId === "voltari" || factionId === "zynarth") {
    const isZynarth = factionId === "zynarth";
    const abilityTitle = isZynarth
      ? (number >= 10 ? "Adaptive Brood" : "Returned Biomass")
      : (number >= 10 ? "Network Breach" : "Conduit Pressure");
    const abilityText = isZynarth
      ? (number >= 10
        ? "The brood changes form after each scripted action, adding one additional late-campaign attack."
        : "The first scripted attack each turn gets +1 value as spent matter returns to the brood.")
      : (number >= 10
        ? "The boss takes one additional scripted action through the compromised network."
        : "The first scripted attack each turn gets +1 value while the conduit remains linked.");
    entry.setup = {
      version: 1,
      bossLife: Math.min(50, 18 + (number - 1) * 3),
      attacksPerTurn: number < 5 ? 2 : number < 9 ? 3 : 4,
      minAttackValue: number < 4 ? 2 : 3,
      maxAttackValue: number < 5 ? 5 : number < 9 ? 6 : 7,
      chapterNumber: number,
      bossAbility: {
        id: number >= 10 ? "final-push" : "first-strike",
        title: abilityTitle,
        text: abilityText,
        tier: number < 5 ? 1 : 2,
        name: `${spec.foe}: ${abilityTitle}`
      },
      playerAdditions: [],
      bossAdditions: [],
      attackTiming: "clear-priority",
      winRoute: "first-uncompleted",
      lossRoute: "retry"
    };
  }
  if (climax) {
    entry.cinematic = {
      kicker: spec.kicker,
      title: spec.title,
      subtitle: spec.subtitle,
      image: spec.image
    };
  }
  return entry;
}

function makeCampaign(factionId, specs) {
  return specs.map((spec, index) => chapter(factionId, index + 1, spec, index === specs.length - 1));
}

const CAMPAIGNS = {
  mekan: makeCampaign("mekan", [
    { slug: "flower-ringed-lake", title: "The Flower-Ringed Lake", hero: "Acama", foe: "The Bone Road Marauders", ally: "Hui", story: "On the Mekan homeworld Teyotl, Acama's wandering people reach a flower-ringed lake and begin the city of San Mikal around a vast ancestral burial complex.", before: "The long migration ends at a lake bright with flowers and spiritual energy, but marauders descend before the exhausted families can raise a wall.", heroLine: "Our ancestors led us here. The living will earn the right to stay.", foeLine: "Bones do not own land.", allyLine: "No, but memory can teach hands how to defend it.", answer: "Raise the lanterns. Let every generation see where San Mikal begins.", after: "The caravan holds the shore and places San Mikal's first stones around a shared burial garden.", foeAfter: "Keep your haunted lake.", allyAfter: "They call it haunted because no one remembers them.", finalLine: "Then our city will remember enough for everyone." },
    { slug: "first-guest", title: "The First Guest", hero: "Acama", foe: "The Silent Ferryman", ally: "Temo", story: "San Mikal's first successful Recursion returns a beloved musician and establishes the law that the dead are Guests who may leave whenever they choose.", before: "A funeral song answers itself from inside the ceremonial chamber, and the first returned spirit asks why the doors are locked.", heroLine: "We invited you home. We did not summon a servant.", foeLine: "Every returned soul owes the living a price.", allyLine: "A Guest who cannot leave is only a captive with flowers.", answer: "Open the chamber and let her choose the length of the dance.", after: "The musician performs until dawn, embraces her descendants, and departs by choice.", foeAfter: "You surrendered eternity.", allyAfter: "We protected consent.", finalLine: "Returning will be a celebration, never an imprisonment." },
    { slug: "lantern-procession", title: "The Procession of Spirits", hero: "Hui", foe: "The Ash-Mask Gang", ally: "Ahu", story: "Hui turns San Mikal's first Procession of Spirits into a civic promise: music, food, masks, and memory belong to the whole community.", before: "Thousands of luminous lanterns guide Guests through streets still smelling of new timber when masked raiders enter the procession.", heroLine: "No one draws steel in a welcome line.", foeLine: "Your ancestors brought their jewelry back for us.", allyLine: "They also brought their stories, and those cannot be stolen.", answer: "Keep the drums moving. The procession will outlast this interruption.", after: "Living dancers and Revenant guardians finish the route together without extinguishing a single lantern.", foeAfter: "This city celebrates like an army.", allyAfter: "An army marches for conquest. We march people home.", finalLine: "Next year even our enemies may attend unmasked." },
    { slug: "spectral-symphony", title: "The Spectral Symphony", hero: "Hui", foe: "Maestro Veyra", ally: "Allegro", story: "A rival conductor binds departed musicians into a perfect eternal orchestra, forcing Allegro to defend joy, imperfection, and the Guests' right to finish their own songs.", before: "Maestro Veyra locks the concert hall and orders the dead to repeat one flawless movement forever.", heroLine: "Music remembered is alive. Music imprisoned is noise.", foeLine: "Perfection requires performers who cannot refuse.", allyLine: "Then perfection has forgotten why anyone listens.", answer: "Break the seals. The final note belongs to the musicians.", after: "The orchestra changes Veyra's score, performs one joyful improvisation, and walks into the Teyotl dawn.", foeAfter: "They ruined my masterpiece.", allyAfter: "They made it theirs.", finalLine: "San Mikal will applaud freedom, even when it misses a note." },
    { slug: "jade-ball", title: "The Jade Ball Tournament", hero: "Ahu", foe: "Champion Xoco", ally: "Monti", story: "The ceremonial Jade Ball Tournament becomes a contest over who owns San Mikal's festival grounds and who may speak for its Guests.", before: "Champion Xoco wagers that one victory should decide who hosts the dead and commands the living crowds.", heroLine: "A festival is not a throne to win.", foeLine: "Everything worth holding has a champion.", allyLine: "Then we will show you a city is held by more than one pair of hands.", answer: "Play the match. The crowd will decide what the score means.", after: "Ahu wins, then invites Xoco's team to lead next year's opening procession.", foeAfter: "You deny yourself the prize.", allyAfter: "We deny the prize the power to divide us.", finalLine: "Competition ends. Community must continue." },
    { slug: "the-empty-chair", title: "The Empty Chair", hero: "Temo", foe: "The Grief Eater", ally: "Allegro", story: "During the Mystical Mask Exchange, a spirit impersonates the beloved dead and teaches San Mikal that remembrance requires specific truth as well as celebration.", before: "Every home in one district sets an extra chair, but the same hungry voice answers from all of them.", heroLine: "You wear beloved faces without carrying their memories.", foeLine: "Grief does not care about the difference.", allyLine: "That is why we must.", answer: "Call each ancestor by the story only their family knows.", after: "The false voices fade when families tell imperfect, specific memories no imitation can steal.", foeAfter: "They will miss the comfort I gave.", allyAfter: "Comfort that consumes them is another hunger.", finalLine: "We honor absence too. The empty chair may remain empty." },
    { slug: "war-of-returning", title: "The War of Returning", hero: "Allegro", foe: "General Calavera", ally: "Acama", story: "General Calavera turns Recursion into permanent military conscription, and Allegro must prove that Teyotl cannot be protected by enslaving its dead.", before: "Calavera marches generations of unwilling soldiers toward San Mikal under banners sewn from funeral cloth.", heroLine: "You turned remembrance into recruitment.", foeLine: "I ended the fear of losing warriors.", allyLine: "By teaching every family to fear burial.", answer: "We free the Guests before we defeat their general.", after: "The returned army lays down its weapons as Allegro breaks the names binding it to Calavera.", foeAfter: "Without my command they are nothing.", allyAfter: "Without your command they are themselves.", finalLine: "No Mekan victory will be built from captive ancestors." },
    { slug: "festival-without-end", title: "The Festival Without End", hero: "Monti", foe: "The Gilded Host", ally: "Temo", story: "Monti confronts a wealthy Host who turns celebration into denial, trapping exhausted citizens and departed Guests inside an endless spectacle.", before: "On the thirteenth dawn of a three-day festival, the drums still sound and the dead can no longer find the road away.", heroLine: "A celebration needs an ending so another can begin.", foeLine: "Joy that stops was never joy.", allyLine: "The dancers are collapsing while you count applause.", answer: "Silence the drums. We will honor the final bow.", after: "Monti extinguishes the central lantern and the Guests depart through a city quiet enough to grieve.", foeAfter: "You killed the wonder.", allyAfter: "We gave wonder back its meaning.", finalLine: "Tomorrow we rest. Next year we dance again." },
    { slug: "the-stolen-names", title: "The Stolen Names", hero: "Temo", foe: "Archivist Silex", ally: "Hui", story: "An archivist erases inconvenient ancestors from the Guest List, threatening the cultural memory and consent on which Mekan Recursion depends.", before: "Families arrive for the Day of Dancing Dead and discover entire bloodlines removed from the ceremonial archive.", heroLine: "A name omitted twice becomes a second death.", foeLine: "History cannot carry everyone.", allyLine: "Then history needs stronger shoulders.", answer: "Open the sealed stacks. We restore every name tonight.", after: "The erased Guests return as citizens recite recovered names through every street in San Mikal.", foeAfter: "You restored criminals beside heroes.", allyAfter: "Memory is testimony, not praise.", finalLine: "We remember the whole life, then judge it honestly." },
    { slug: "siege-of-san-mikal", title: "The Siege of San Mikal", hero: "Allegro", foe: "The Pale Conquistador", ally: "Ahu", story: "An invader crosses Teyotl to seize the Recursion chambers and build an empire whose soldiers return after every defeat.", before: "The Pale Conquistador surrounds San Mikal and offers peace in exchange for the city's dead.", heroLine: "Our Guests are people, not weapons in storage.", foeLine: "Every empire is built from resources others sentimentalize.", allyLine: "Then your empire has never met a resource that can refuse.", answer: "Invite every defender, living and departed. No one is commanded to stay.", after: "Voluntary Guests hold the gates long enough for the invader's conscript army to see what choice looks like.", foeAfter: "Your mercy made them dangerous.", allyAfter: "Their freedom did.", finalLine: "San Mikal survives because anyone may leave it." },
    { slug: "one-more-song", title: "One More Song", hero: "Allegro", foe: "The Quiet Plague", ally: "Monti", story: "A plague attacking memory reveals that San Mikal's oldest ceremonial stones do more than preserve minds: they are receivers entangled with a distant world called Reath.", before: "Songs lose verses and Guests flicker while an ancient stone beneath the burial complex begins answering memories from an alien sky.", heroLine: "If memory fails, we teach it to begin again.", foeLine: "All songs end in silence.", allyLine: "Silence is where musicians breathe, and where distant voices can be heard.", answer: "Share every story. No archive and no world stands alone tonight.", after: "The city distributes its memories among thousands of voices, and the awakened stone resolves into a stable Timetwister path.", foeAfter: "You made your history inconsistent.", allyAfter: "We made it alive enough to travel.", finalLine: "Teyotl is our home. Reath is the invitation beyond it." },
    { slug: "grand-reunion", title: "The Procession to Reath", hero: "Allegro", foe: "The Keeper Beyond", ally: "Acama", story: "A voluntary procession of living Mekan and willing Guests crosses the Timetwister from homeworld Teyotl to Reath, where histories from many other homeworlds meet.", before: "The Keeper Beyond warns that a person carried as memory through an entangled stone may arrive changed, while Reath answers with unfamiliar songs.", heroLine: "We carry no captive dead and claim no second homeland.", foeLine: "Mortals always mistake an open road for ownership.", allyLine: "Then we arrive as Guests and expect to leave as freely as our own.", answer: "Open the path for those who consent. San Mikal keeps the light for their return.", after: "The procession re-embodies on Reath beside strangers from distant worlds, while every traveler remains entangled with a living record on Teyotl.", foeAfter: "The road now joins histories that were never meant to meet.", allyAfter: "Meeting does not erase where anyone began.", finalLine: "Teyotl is our origin. Reath is the convergence point, and the next celebration begins with introductions.", kicker: "The procession between worlds", subtitle: "San Mikal sends Guests to Reath without surrendering their home or their choice.", image: "/assets/gauntlet/mekan-emblem.svg" }
  ]),
  jali: makeCampaign("jali", [
    { slug: "line-after-loss", title: "The Age of a Thousand Clouds", hero: "Watane", foe: "Lord Haruto", ally: "Basho", story: "On the Jali homeworld Aozora, Watane learns that a bested warrior can return briefly as a Revenant while the floating clans of the Celestial Archipelago still answer to the distant Heavenly Court.", before: "Haruto's cavalry breaks a bridge formation above Aozora's cloud sea, and a fallen guardian rises as light to show Watane where the line failed.", heroLine: "Defeat opened a place. Memory may hold it, but it may not own the dead.", foeLine: "A ghost is only a weakness pretending to stand.", allyLine: "Then watch the living change formation around what the fallen taught us.", answer: "Reform the line and let the Revenant choose its final step.", after: "The counterattack saves the island without binding the guardian beyond the moment it freely gives.", foeAfter: "You turned loss into strength.", allyAfter: "We turned it into instruction.", finalLine: "Nothing endures unchanged, but nothing loved vanishes without consequence." },
    { slug: "three-hidden-banners", title: "The War of the Fractured Sky", hero: "Basho", foe: "The Mirror Clan", ally: "Watane", story: "The Celestial Sovereign disappears without an heir, and rival tengu, kitsune, oni, and awakened-object clans divide Aozora's archipelago between competing claimants.", before: "Amakumo burns beneath three hidden banners while every clan claims that its ancestral memory names the lawful successor.", heroLine: "A memory can testify. It cannot crown the speaker who summoned it.", foeLine: "Our ancestors chose us before your formation existed.", allyLine: "Then reveal the witnesses and the hands directing them.", answer: "Three banners down. We expose every claimant at once.", after: "Basho proves that each camp has edited the same succession rite, but the revelation arrives too late to prevent the Heavenly Court's collapse.", foeAfter: "Without one history, there can be no realm.", allyAfter: "Without honest history, there can only be obedience.", finalLine: "The sky fractures, and the Jali enter an age of Cloud Daimyo." },
    { slug: "floating-city", title: "The Storm Conqueror", hero: "Watane", foe: "The Coalition of Seven Peaks", ally: "Yamabuki-no-Kami", story: "Yamabuki-no-Kami begins unifying Aozora from the mobile city Katana, combining rival yokai traditions and weaponizing the destruction of Reflections.", before: "Seven daimyo surround Katana while phantom fleets fill the sky and conceal Yamabuki's real descent through the storm.", heroLine: "A Reflection need not be real for its shattering to change the battle.", foeLine: "Your borrowed clans will abandon one another when the illusion breaks.", allyLine: "They fight together because I offered a future larger than ancestry.", answer: "Hold all three lanes until the phantom fleet draws their eyes.", after: "Katana rises beyond the coalition's reach, and Yamabuki's Shattering Storm makes unification seem possible.", foeAfter: "You conquered the sky with a lie.", allyAfter: "No. The lie revealed where certainty made you blind.", finalLine: "Katana becomes the moving heart of a new Jali order." },
    { slug: "bested-prince", title: "The Night of a Thousand Reflections", hero: "Watane", foe: "Prince Daigo", ally: "Yamabuki-no-Kami", story: "Yamabuki seeks the Mirror of Eternity, an archive of every sovereign's memories, while Prince Daigo betrays him to stop one ruler from possessing the Jali past.", before: "Rebels surround the Temple of Ten Thousand Dreams as Daigo prepares to shatter hundreds of Reflections at once.", heroLine: "A ruler may consult memory. No ruler may possess it.", foeLine: "Then help me bury the conqueror with the mirror he would steal.", allyLine: "If the old court controls eternity, no living reform survives.", answer: "Evacuate the temple and sever the Mirror before either claimant can command it.", after: "The simultaneous shattering destroys the temple. Yamabuki vanishes, leaving only a translucent silhouette in the storm.", foeAfter: "The conqueror is finally bested.", allyAfter: "Or remembered strongly enough to return.", finalLine: "No body falls from the ruins, and Aozora inherits an unfinished unification." },
    { slug: "storm-formation", title: "The Golden Heavens", hero: "Watane", foe: "The Thunder Ronin", ally: "Hinata-no-Mikoto", story: "Hinata spends years turning Yamabuki's conquests into a coalition, building Tenkyo while the young scholar Seimei-no-Mikoto studies how shared memories change when former enemies remember together.", before: "The Thunder Ronin attacks Tenkyo's unfinished bridges during the first interclan assembly, hoping one storm will scatter Hinata's fragile alliance into its old loyalties.", heroLine: "A formation is a promise between different warriors, not a bloodline painted on stone.", foeLine: "Promises dissolve when the bridge beneath them does.", allyLine: "I promised every clan a place here. If Tenkyo falls today, they will remember my promise as another conqueror's trick.", answer: "Anchor each lane to another clan. Seimei will record whose memories guide the rescue, and whose choices make it possible.", after: "Tengu, kitsune, oni, yuki-onna, and tsukumogami hold the city as one moving formation. Seimei records that cooperation altered the recalled spirits as surely as it altered the living.", foeAfter: "You built unity from incompatible spirits.", allyAfter: "No. They built it while I gave them somewhere to meet.", finalLine: "Tenkyo becomes the City of a Thousand Reflections, and Seimei begins asking what a Reflection remembers." },
    { slug: "revenant-famine", title: "The Mirror That Remembered Everything", hero: "Watane", foe: "The White Abbot", ally: "Seimei-no-Mikoto", story: "Years into Hinata's prosperous reign, her fear that unity will die with its witnesses drives the reconstruction of the Mirror of Eternity, where Seimei discovers that recovered memories are arriving from lives Aozora never lived.", before: "Hinata asks the Mirror for one lost adviser and receives three versions of her: one loving, one furious, and one who remembers Hinata as a tyrant.", heroLine: "Remembrance without limits turns a person into raw material.", foeLine: "Oblivion is the only true cruelty. Let every version return.", allyLine: "I studied these voices when they were faint. These are not merely our dead; they are realities that never became ours.", answer: "Close the retrieval chambers. Hinata must hear the contradictions before grief chooses among them.", after: "Hinata seals the project she commissioned. Seimei proves that destroyed Reflections and abandoned futures have accumulated into a void now arranging its own answers.", foeAfter: "You chose loss when eternity opened.", allyAfter: "We chose one shared reality in which apology, consequence, and choice still mean something.", finalLine: "From inside the darkened Mirror, several voices whisper Seimei's name at different ages." },
    { slug: "paper-moon-coup", title: "The Patient Sovereign", hero: "Basho", foe: "Minister Kuro", ally: "Amateru-no-Kami", story: "After Hinata withdraws from public life, years of argument over the sealed Mirror divide her coalition. Amateru patiently negotiates limits on Memory while Minister Kuro counterfeits ancestors to make restraint look like betrayal.", before: "Masked spirits fill Tenkyo's chamber with mutually exclusive commands. Amateru has the votes to delay war, but exposing Kuro will also expose compromises that cost him old allies.", heroLine: "A formation is revealed so every witness can inspect it.", foeLine: "Truth is the memory powerful enough to hold the room.", allyLine: "If my coalition survives only by hiding its bargains, it deserves to break in daylight.", answer: "Name each source, expose every conduit, and publish our own concessions beside Kuro's lies.", after: "The false Revenants collapse under scrutiny. Amateru loses trusted allies but gains an honest mandate to confront the armies gathering above the Sea of Silent Clouds.", foeAfter: "People preferred the history I gave them.", allyAfter: "Preference does not make an ancestor, and patience does not excuse secrecy.", finalLine: "Memory earns authority only when the living may question it." },
    { slug: "falling-katana", title: "The Battle of Silent Clouds", hero: "Watane", foe: "The Eastern Cloud Alliance", ally: "Amateru-no-Kami", story: "Aozora's greatest civil battle awakens the Mirror, showing every warrior a different outcome and forcing Amateru to sacrifice victory to preserve reality.", before: "Katana descends between rival fleets while the Mirror overlays triumph, defeat, and the city's destruction on the same sky.", heroLine: "Your philosophy will not change gravity, but our formation can change where the city lands.", foeLine: "In my history, you already surrendered.", allyLine: "Then we sever the instrument writing victories for both of us.", answer: "Break the spiritual conduits and turn Katana's fall into a controlled descent.", after: "The Mirror's battlefield collapses. Amateru's restraint wins the surviving daimyo's loyalty and begins the Era of the Veiled Sky.", foeAfter: "You abandoned the perfect victory.", allyAfter: "A victory that erases the world cannot govern it.", finalLine: "Katana lands intact, and peace begins with a weapon left unused." },
    { slug: "warrior-without-memory", title: "The Era of the Veiled Sky", hero: "Watane", foe: "Nameless Revenant", ally: "Seimei-no-Mikoto", story: "Generations of peace, art, and regulated Memory pass on Aozora until a Revenant returns without identity and with memories of futures beyond the homeworld.", before: "A nameless spirit walks from a forgotten shrine, recognizes no clan, and describes stars that Aozora's astronomers have never charted.", heroLine: "You may choose before you remember.", foeLine: "Choice without a past is an empty weapon.", allyLine: "Or the first evidence that the Mirror reaches farther than our dead.", answer: "Stand with us for this battle, then leave if the answer feels false.", after: "The spirit protects Katana, names a distant world called Reath, and departs to search for its own history.", foeAfter: "I still do not know my name.", allyAfter: "Now you know one choice you made freely.", finalLine: "The Veiled Sky cannot hide that another world has begun reflecting Aozora." },
    { slug: "seven-clan-war", title: "The Return of the Forgotten", hero: "Basho", foe: "The Forgotten Sovereign", ally: "Watane", story: "Reality Fractures spread across Aozora as a consciousness formed from abandoned possibilities offers every clan the history it most wants to remember.", before: "Katana becomes seven overlapping cities: in one Watane died young, in another Basho serves the Mirror Clan, and in a third Yamabuki never fell.", heroLine: "If all seven histories are sacred, none grants permission to erase the others.", foeLine: "I saved you. We were never born. I remember your surrender tomorrow. We offer the freedom I forbid.", allyLine: "It is not speaking with many voices. It is forcing contradictions to pretend they are agreement.", answer: "Reveal every formation and compare the spaces the Sovereign cannot reconcile.", after: "The contradictions expose a single hunger beneath its promises: the void needs the living to remember it into permanence.", foeAfter: "Without every past, you are whole. Without one past, we are nothing. Choose all of me.", allyAfter: "We choose the freedom to release what no longer belongs to us.", finalLine: "The Jali prepare to fight an enemy strengthened by every memory they summon." },
    { slug: "last-revenant", title: "The Rite of Final Remembrance", hero: "Watane", foe: "The Forgotten Sovereign", ally: "Seimei-no-Mikoto", story: "The Jali can save Aozora only if Revenants freely surrender the chance to be recalled again, beginning with Yamabuki and the people whose unfinished hopes the living have used for generations.", before: "Ancient armies fill the sky. Yamabuki returns at their head and realizes that staying would let him finish unification in one possible Aozora while condemning every living descendant to the Sovereign.", heroLine: "We asked the bested to guide us so often that we stopped asking whether they wished to rest.", foeLine: "I keep every farewell. We erase no one. I will not allow them to choose oblivion.", allyLine: "The rite destroys the recall pattern, not the life that was lived. I must release my own teacher before I can ask anyone else.", answer: "Open the rite to each spirit alone. No clan, ruler, or descendant may answer in their place.", after: "Seimei releases his teacher. Parents refuse another borrowed reunion; soldiers lay down wars their heirs kept reopening; and Yamabuki relinquishes the empire he could still complete. Their separate choices tear thousands of faces from the Sovereign.", foeAfter: "They abandon you. I preserve them. We are being murdered by consent.", allyAfter: "Their voices end because they chose an ending. What they changed in us remains beyond your reach.", finalLine: "Watane thanks Yamabuki without asking him to return, and the Storm Conqueror enters the Final Passing." },
    { slug: "formation-eternal", title: "The Last Reflection", hero: "Watane", foe: "The Forgotten Sovereign", ally: "Basho", story: "The Mirror shatters above Aozora, revealing that one fragment is entangled with a Timetwister receiver on Reath and that the two worlds have been exchanging stray memory-patterns for centuries.", before: "The Sovereign becomes empty armor around a thousand possible faces while Katana's last Reflection shows a world of reptilian legions, living forests, machines, and distant newcomers.", heroLine: "A formation without lives is only geometry. We choose one world and accept that it can change.", foeLine: "You win. We have already returned. I never existed. Reath remembers me before you arrive.", allyLine: "Contradiction is not prophecy. Let the next choice belong to people you cannot reduce to possibilities.", answer: "Break the Mirror, preserve the entangled fragment, and let every lane answer differently.", after: "Aozora stabilizes. Katana's navigators use the fragment as an error-correcting identity reference and open a narrow Timetwister passage to Reath.", foeAfter: "The road will join histories that were never meant to meet.", allyAfter: "Meeting does not erase where any history began.", finalLine: "Aozora remains our home. Reath is the convergence point, and the Jali cross as witnesses rather than ghosts.", kicker: "The heavens remember", subtitle: "The Jali save Aozora by accepting impermanence, then open a disciplined path to Reath.", image: "/assets/gauntlet/jali-emblem.svg" }
  ]),
  gracus: makeCampaign("gracus", [
    { slug: "cliffs-of-athun", title: "The City of Questions", hero: "Epicura", foe: "Alexiti", ally: "Socratus", story: "On the Gracus homeworld Thalassa, Epicura opposes Alexiti's demand that Athun conquer rebellious city-states before uncertainty becomes civil war.", before: "Sunlight crosses Athun's marble harbors as Alexiti returns to the Hall of Voices with attacked trade routes, missing soldiers, and a demand to march.", heroLine: "If every disagreement becomes rebellion, every neighbor eventually becomes an enemy.", foeLine: "If every enemy becomes a debate, no one will remain to finish the argument.", allyLine: "Before choosing war, ask who profits when both answers require it.", answer: "We investigate the coast and defend its people without conquering them.", after: "Epicura wins authority for a limited mission, but Alexiti leaves certain that hesitation will cost Athun dearly.", foeAfter: "Bring back certainty, or I will bring back order.", allyAfter: "Certainty is usually the first casualty of an honest question.", finalLine: "Then let Athun see us reason under pressure." },
    { slug: "first-minotaur", title: "The First Crack", hero: "Epicura", foe: "Governor Nemeon", ally: "Themin", story: "Epicura and Themin expose provocations that have turned a frightened coastal settlement against Athun.", before: "Governor Nemeon has seized a port and blames Athun for attacks that arrive under contradictory banners.", heroLine: "You cannot protect a city by deciding every unanswered question is treason.", foeLine: "Questions did not bury my scouts.", allyLine: "No, but forged orders sent them to the wrong pass.", answer: "Hold the harbor, compare the orders, and leave Nemeon a road back from fear.", after: "The forged seals match no city-state. Someone has manufactured evidence for every side.", foeAfter: "I defended my people from a lie.", allyAfter: "Now help us find the author.", finalLine: "Athun returns with proof of danger and no convenient enemy." },
    { slug: "towering-follow-up", title: "The Wall of Leo", hero: "Epicura", foe: "Leo", ally: "Themin", story: "The mountain defender Leo seals his passes after receiving false commands from Athun, forcing Epicura to earn a hearing through a controlled war exercise.", before: "Caravans burn below Leo's gates while each surviving messenger carries a different order bearing Athun's seal.", heroLine: "Your wall preserved lives. It is now preserving the lie that isolated you.", foeLine: "Stone does not forge orders or vanish in the night.", allyLine: "Stone also cannot tell which friend is knocking.", answer: "Test our formation. If we break your defense, hear the evidence we carried through it.", after: "Epicura outmaneuvers Leo without breaching the civilian refuge, and the defender joins the investigation.", foeAfter: "I still do not trust Athun.", allyAfter: "Neither do we. We trust what survives examination.", finalLine: "Then stand with us until the source is visible." },
    { slug: "tribute-refused", title: "The Question of Socratus", hero: "Socratus", foe: "The Certainty League", ally: "Epicura", story: "Socratus challenges Athun's Senate, its frightened citizens, and Epicura while tracing the forged orders to a buried sanctuary.", before: "Competing factions fill Athun's plazas, each promising safety if the city stops listening to everyone else.", heroLine: "A leader who cannot answer questions is already ruled by the answer they fear.", foeLine: "Debate is a luxury during invasion.", allyLine: "Then name the invader instead of arresting whoever asks.", answer: "Open the archives, compare every seal, and follow the contradiction beneath the mountains.", after: "The evidence points to an abandoned sanctuary older than Athun, but Alexiti acts before Epicura can enter it.", foeAfter: "While you questioned, the army restored the streets.", allyAfter: "A silent street can hide a marching prison.", finalLine: "We found where the lies began. Now we survive what they enabled." },
    { slug: "arena-of-echoes", title: "Alexiti's Peace", hero: "Epicura", foe: "Alexiti", ally: "Leo", story: "Alexiti occupies Athun without massacre and offers a peaceful authoritarian order that many exhausted citizens welcome.", before: "Military governors replace the Senate, roads reopen, and Athun becomes calm enough to make coercion look like rescue.", heroLine: "You gave the city silence and called the absence of objection consent.", foeLine: "Silence is preferable to screaming.", allyLine: "A wall may protect a voice. It must never become the reason voices disappear.", answer: "We leave Athun alive, gather proof, and return before emergency becomes tradition.", after: "Alexiti lets Epicura depart, confident that philosophy will fail outside the safety his army created.", foeAfter: "When reason fails you, Athun will still be here.", allyAfter: "If no one may disagree with Athun, only the buildings remain.", finalLine: "We will return with an answer stronger than obedience." },
    { slug: "giants-coast", title: "Everything Flows", hero: "Hera", foe: "The Moving Statues", ally: "Epicura", story: "The philosopher Hera reveals that Thalassa's oldest monuments are cracking and that the first Gracus imprisoned something beneath Athun.", before: "Statues change position between observations while carvings of the first awakening shed stone from an erased panel.", heroLine: "We built a civilization from stone and mistook endurance for permanence.", foeLine: "RETURN TO THE FORM THAT MADE YOU.", allyLine: "A beginning is evidence, not ownership.", answer: "Record every change, free the trapped scholars, and open the erased wall.", after: "Behind the panel lies an image of the first Gracus containing a black polyhedral stone.", foeAfter: "ONE STONE. ONE MEMORY. ONE PEACE.", allyAfter: "Peace that erases the speaker is only quiet matter.", finalLine: "Nothing remains fixed, which means neither does our fate." },
    { slug: "broken-horn", title: "The Labyrinth", hero: "Epicura", foe: "Keeper Theros", ally: "Hera", story: "Beneath Athun, mythic creatures guard the Keepers of the First Stone, who admit engineering the crisis so the Gracus would accept one ruler.", before: "Minotaurs, Gorgons, and Gryphons defend corridors older than every Gracus city-state.", heroLine: "You created the fear, then offered submission as its cure.", foeLine: "We reminded a divided people that unity is survival.", allyLine: "A conclusion built from falsified evidence is staging, not unity.", answer: "Free the creatures from the lattice and carry the Keepers' records to Athun.", after: "Theros reveals that Alexiti's centralized government was simply the easiest system to capture.", foeAfter: "The conqueror gathered every institution into one hand for us.", allyAfter: "Then one honest fracture can break your grip.", finalLine: "We return before the Keepers close that hand." },
    { slug: "three-arena-war", title: "The Conqueror", hero: "Alexiti", foe: "Keeper Theros", ally: "Epicura", story: "The Keepers attempt to assassinate Alexiti and seize Athun, forcing conqueror and philosopher into an uneasy alliance.", before: "The regime's single chain of command becomes the Keepers' weapon as compromised officers turn on Alexiti.", heroLine: "I united the Gracus. I did not surrender them to ghosts beneath the city.", foeLine: "You made one government. We need capture only one throne.", allyLine: "Then perhaps today we can disagree about tomorrow.", answer: "Alexiti holds the palace while Epicura restores independent command to every district.", after: "Athun survives when its neighborhoods act without waiting for the captured central authority.", foeAfter: "You replaced order with contradiction.", allyAfter: "We replaced a single point of failure with citizens.", finalLine: "I still intend to unite the Gracus. Today I help keep them alive." },
    { slug: "minotaur-revolt", title: "The Hero of Stone", hero: "Chilis", foe: "The Marble Hydra", ally: "Themin", story: "The Keepers awaken a colossal mythic creature beneath Athun, and every Gracus philosophy becomes a different tool in the defense.", before: "The Marble Hydra breaks through the agora while citizens flee between collapsing monuments.", heroLine: "There is a monster threatening our people. I require no deeper argument.", foeLine: "MANY VOICES BREAK. ONE HUNGER ENDURES.", allyLine: "Then we give every voice a task it performs better than hunger.", answer: "Leo holds the routes, Themin moves the line, Hera reads the changes, and Chilis strikes after the city is clear.", after: "The Hydra falls through coordination no single ruler or doctrine could have produced.", foeAfter: "DISAGREEMENT SHOULD HAVE DIVIDED YOU.", allyAfter: "It gave us more than one answer.", finalLine: "Build the statues later. The people are the victory." },
    { slug: "quiet-arena", title: "The First Stone", hero: "Epicura", foe: "The First Stone", ally: "Socratus", story: "The Keepers try to merge every Gracus mind into the First Stone, promising harmony without loneliness, uncertainty, or war.", before: "Deep below Athun, the First Stone offers each Gracus the same painless thought and calls it peace.", heroLine: "A civilization without disagreement has no citizens left inside it.", foeLine: "ONE MIND CANNOT BETRAY ITSELF.", allyLine: "Can it learn, if it can never discover that it is wrong?", answer: "Sever the control lattice and let every mind choose separation.", after: "The lattice collapses. The First Stone wakes long enough to unfold into a Timetwister aperture aimed beyond Thalassa.", foeAfter: "DIVISION SEEKS CONVERGENCE.", allyAfter: "That sounds less like a threat than a destination.", finalLine: "Athun is unfinished and alive. We will learn what called to it." },
    { slug: "the-impossible-wager", title: "The Stone Between Stars", hero: "Epicura", foe: "The Keeper Remnant", ally: "Alexiti", story: "A Gracus delegation crosses the First Stone's Timetwister, leaving Thalassa behind as an encoded biological pattern is reconstructed on Reath.", before: "The aperture can transmit only a bounded pattern: no army, no city, and no guarantee the receiving world will understand what arrives.", heroLine: "We do not abandon Thalassa. We carry its question to another world.", foeLine: "The crossing will copy you and leave the original to die.", allyLine: "Then the choice belongs to those who understand its cost.", answer: "Send a voluntary delegation, verified memories, and enough seed material to return the answer home.", after: "Seven Gracus awaken in newly assembled stone bodies beneath an unfamiliar sky.", foeAfter: "Athun will forget you.", allyAfter: "Athun argues about everything. It will argue about us for centuries.", finalLine: "This is not our origin. It is our arrival on Reath." },
    { slug: "worthy-contest", title: "The World of Meeting", hero: "Epicura", foe: "The Convergence Panic", ally: "Socratus", story: "On Reath, the Gracus meet peoples from other homeworlds and prevent frightened first contact from becoming the war every faction expects.", before: "Vanguard weapons, Zynarth scouts, Voltari anchors, and Gracus hoplites surround the same active receiver.", heroLine: "Four worlds arrived at one question. None of us owns the premise.", foeLine: "UNKNOWN FORCES: Disarm first. Explanations follow survival.", allyLine: "If everyone obeys that rule, who remains to explain?", answer: "Hold formation, exchange homeworld records, and let the Timetwister prove each arrival path.", after: "The records agree: Reath is the convergence point, not the birthplace of the peoples standing upon it.", foeAfter: "UNKNOWN FORCES: Then what called all of us here?", allyAfter: "A better question than who should rule the meeting.", finalLine: "Thalassa made us Gracus. Reath will test what we become among others.", kicker: "Reason crosses worlds", subtitle: "The Gracus leave their origin intact and enter Reath's unfinished argument.", image: "/assets/gauntlet/gracus-emblem.svg" }
  ]),
  indela: makeCampaign("indela", [
    { slug: "first-omen", title: "The Founding Flame", hero: "Katel", foe: "Dean Var", ally: "Chandragupta", story: "On the Indela homeworld Varuna, rival beetle academies contest Kashi's libraries until Katel and Chandragupta propose a kingdom founded on shared knowledge.", before: "Dean Var attacks Kashi before its open academy can draw fire and ice students away from the older city-states.", heroLine: "A school that fears another question has already surrendered its answer.", foeLine: "Knowledge belongs to the city strong enough to guard it.", allyLine: "Then we will build a realm strong enough to keep every school open.", answer: "Defend the libraries. Harm no student who lays down a spell.", after: "Kashi holds, and Chandragupta offers protection in exchange for the academy's counsel rather than its obedience.", foeAfter: "You traded independence for an empire.", allyAfter: "We offered a concord whose terms remain visible.", finalLine: "Kashi joins only if fire and ice enter by the same gate." },
    { slug: "academy-of-omens", title: "The First Concord", hero: "Katel", foe: "The Three Regional Lords", ally: "Chandragupta", story: "Katel helps unite Varuna's divided Indela lands while insisting that conquest cannot close the academies or make scholarship serve one ruler.", before: "Three regional lords reject Chandragupta's concord and prepare to burn every academy that accepts it.", heroLine: "Unity is useful only if thought remains free inside it.", foeLine: "One kingdom requires one authorized truth.", allyLine: "A ruler can coordinate roads and armies without owning the stars.", answer: "Protect the Frozen Lotus delegation and break the siege together.", after: "The final rulers join the concord after mixed elemental formations defeat armies built around a single discipline.", foeAfter: "Your scholars now decide politics.", allyAfter: "They reveal consequences. Citizens still decide what follows.", finalLine: "Kashi becomes Varuna's intellectual capital, not its unquestioned throne." },
    { slug: "second-reading", title: "The Empire of Knowledge", hero: "Vishnugupta", foe: "The Road Reavers", ally: "Vatsyayana", story: "Trade routes, village schools, and traveling scholars turn the united Indela realm into a golden age centered on Kashi rather than military expansion.", before: "Raiders sever the Scholar's Road while thousands of students and copied manuscripts are still crossing Varuna toward Kashi.", heroLine: "A road carries more power in a lesson than in a marching column.", foeLine: "Books cannot defend the hands holding them.", allyLine: "Teachers can, when every lesson includes preparation.", answer: "Ice shields the caravan. Fire clears only the road ahead.", after: "The scholars arrive, and Vatsyayana establishes public colleges beyond the capital so Kashi's learning cannot become a private monopoly.", foeAfter: "You spent an army saving apprentices.", allyAfter: "We saved the people who will teach the next one.", finalLine: "An empire of knowledge grows by multiplication, not possession." },
    { slug: "odd-even-war", title: "The Stars Above Kashi", hero: "Aryabhata", foe: "The Fixed-Sphere Orthodoxy", ally: "Vara", story: "Aryabhata and Vara discover that Varuna's elemental currents follow mathematical relations to its moons and stars, threatening doctrines built on fire and ice as eternal opposites.", before: "The Orthodoxy attacks Kashi's new observatory before its enchanted lenses can complete the longest night of measurements.", heroLine: "The sky does not become heresy because our table was too small.", foeLine: "Your numbers reduce sacred flame and frost to machinery.", allyLine: "Measurement does not empty wonder. It gives wonder a shape we can share.", answer: "Hold the observatory through dawn and publish every calculation.", after: "A luminous mandala appears above Kashi as fire and ice resolve into two expressions of one deeper field.", foeAfter: "You have unsettled every academy.", allyAfter: "Then every academy has something real to study.", finalLine: "Varuna's heavens have made opposition into relationship." },
    { slug: "cost-of-prophecy", title: "The Elemental Equation", hero: "Katel", foe: "The Unbound Experiment", ally: "Aryabhata", story: "A prototype combining fire and ice escapes its laboratory, forcing Katel to prove that synthesis requires restraint as well as ambition.", before: "A white elemental storm forms inside Kashi and begins rewriting every spell it touches.", heroLine: "Discovery gives us responsibility before it gives us power.", foeLine: "COMBINATION REQUIRES NO CONSENT.", allyLine: "The equation predicts growth unless we separate its feedback terms.", answer: "Freeze the outer ring, vent the heat, and reveal the sequence one step at a time.", after: "The construct collapses into a stable crystal that preserves both elemental signatures without consuming either.", foeAfter: "POTENTIAL REDUCED.", allyAfter: "Potential measured.", finalLine: "Harmony is disciplined interaction, not limitless fusion." },
    { slug: "library-of-maybe", title: "The Poet and the Flame", hero: "Kalidasa", foe: "The Escaped Manuscript", ally: "Katel", story: "Kalidasa's enchanted poetry makes history and imagined futures visible, then escapes its pages and shows Kashi burning in contradictory ways.", before: "Figures from a living manuscript walk into the Festival of Enlightenment, each insisting its vision is Varuna's certain future.", heroLine: "A poem reveals a possibility; it does not issue an order.", foeLine: "WHAT IS IMAGINED HAS ALREADY BEGUN.", allyLine: "Then imagination must answer to the people who live with its effects.", answer: "Let every vision finish, compare their differences, and bind none as prophecy.", after: "Kalidasa restores the manuscript, but one recurring image of fire beneath Kashi remains unexplained.", foeAfter: "THE CITY STILL BURNS.", allyAfter: "A warning can guide us without ruling us.", finalLine: "Art enlarges knowledge because it lets us examine futures before choosing them." },
    { slug: "the-null-card", title: "The Schism of Fire and Frost", hero: "Katel", foe: "Kumara's Ascendant Circle", ally: "Vara", story: "Kumara demands that Kashi weaponize the unified elemental field while Vara's Frozen Lotus scholars call for a permanent halt to dangerous research.", before: "A laboratory explosion divides the academy, and armed students occupy the fire halls and frozen sanctuaries.", heroLine: "Fire without wisdom consumes; ice without change preserves only what already exists.", foeLine: "Restraint has become fear wearing ceremonial robes.", allyLine: "Ambition has become appetite carrying a research seal.", answer: "Protect both orders, expose the failed safeguards, and rebuild the experiment together.", after: "Katel combines flame and frost to restore the central laboratory, renewing the Elemental Concord without declaring either order innocent.", foeAfter: "You saved our rivals from the consequences of delay.", allyAfter: "He saved all of us from the consequences of certainty.", finalLine: "Neither discipline can sustain a civilization alone." },
    { slug: "frozen-forecast", title: "The Shadows Beyond the Mountains", hero: "Skandagupta", foe: "The Antlered Confederation", ally: "Katel", story: "Northern kingdoms armed with anti-magic artifacts invade Varuna while Kashi is still healing from its internal schism.", before: "Border cities fall and refugees cross the Frozen Pass as the confederation advances toward Kashi's archives.", heroLine: "They prepared for our strongest spells. We will win through coordination.", foeLine: "Your golden age ends beyond this pass.", allyLine: "A civilization is more than the force it can project at a border.", answer: "Ice holds the pass. Fire breaks the artifacts only after civilians clear the valley.", after: "Skandagupta saves Kashi, but the treasury, libraries, and a generation of scholars pay for the victory.", foeAfter: "We failed to take your capital.", allyAfter: "And still changed what it can afford to become.", finalLine: "Survival is a beginning. We must now decide what the survivors preserve." },
    { slug: "burning-proof", title: "The Fading Mandala", hero: "Katel", foe: "The Provincial Compact", ally: "Vishnugupta", story: "Varuna's Indela empire fragments after the war, and Katel chooses to rescue scholars and evidence rather than enforce Kashi's fading political authority.", before: "Regional rulers seize observatories and burn libraries while demanding that Kashi spend its last strength restoring their obedience.", heroLine: "An empire may end without taking its knowledge into the grave.", foeLine: "Without authority your archive will become plunder.", allyLine: "Then distribute copies faster than any conqueror can gather them.", answer: "Evacuate the scholars, recover the manuscripts, and abandon empty symbols of rule.", after: "Independent academies receive copies of Kashi's work even as the old capital loses control of distant provinces.", foeAfter: "You chose books over your realm.", allyAfter: "We chose what could outlive it.", finalLine: "The mandala fades, but its pattern can be drawn again." },
    { slug: "omen-market", title: "The Eternal Archive", hero: "Vatsyayana", foe: "The Ash Broker", ally: "Kalidasa", story: "As collapse accelerates, Kashi builds an archive that preserves mathematics, astronomy, poetry, pedagogy, and the record of its own failures.", before: "The Ash Broker offers to fund the archive if inconvenient theories and defeated provinces are erased from its crystals.", heroLine: "Knowledge edited for a patron is an advertisement to the future.", foeLine: "The future cannot carry everything.", allyLine: "Then it needs context for every choice we make about what survives.", answer: "Open the vault to every school and preserve corrections beside discoveries.", after: "Thousands of scholars encode the Golden Age into redundant crystals distributed across Varuna.", foeAfter: "Your archive contradicts itself.", allyAfter: "Across centuries, so does every honest civilization.", finalLine: "Let descendants see not only what we knew, but how we learned." },
    { slug: "city-of-one-answer", title: "The Last Spell", hero: "Katel", foe: "The Unbound Convergence", ally: "Aryabhata", story: "The elemental field beneath Kashi ruptures, and Katel gathers Varuna's surviving scholars for a final synthesis that can save the city and the Eternal Archive.", before: "Fire storms and frozen fractures climb Kashi's towers while an entity of uncontrolled elemental energy awakens below the academy.", heroLine: "We preserve the archive so others may surpass it, not worship it.", foeLine: "ALL DIFFERENCE RETURNS TO POWER.", allyLine: "Three conduits can stabilize the field if the final pattern has a living anchor.", answer: "Balance every lane. I will hold the center when the equation closes.", after: "The Convergence collapses, the archive survives, and Katel disappears inside a sphere where fire and ice become white light.", foeAfter: "ANCHOR UNRESOLVED.", allyAfter: "His staff remains, but the instruments cannot say whether he died or crossed elsewhere.", finalLine: "Knowledge belongs to those who carry it forward." },
    { slug: "open-future", title: "The Knowledge That Endures", hero: "A Young Archivist", foe: "The Final Omen", ally: "Vara", story: "Centuries later on Varuna, a new Indela generation defends Kashi's surviving archive and discovers that Aryabhata's celestial pattern includes a receiver signal from a distant world called Reath.", before: "The Final Omen claims Kashi must seal itself forever, just as Katel's suspended staff responds to a sequence arriving from beyond Varuna's sky.", heroLine: "Preservation without new questions turns an archive into a tomb.", foeLine: "THE FUTURE IS SAFEST WHEN CLOSED.", allyLine: "Katel saved knowledge for students who would change it, not merely repeat it.", answer: "Open every observatory. Verify the signal, preserve our origin, and answer without leaving Varuna undefended.", after: "Kashi sends a parity-encoded reply through the dormant Timetwister receiver; Reath answers, but the Indela campaign ends at home beneath Varuna's luminous mandala.", foeAfter: "CONTACT CREATES UNCERTAINTY.", allyAfter: "So does every honest discovery.", finalLine: "Varuna is our world. Reath is a question for the age that follows.", kicker: "The archive answers the stars", subtitle: "Kashi survives its empire and hears another world without abandoning its own.", image: "/assets/gauntlet/indela-emblem.svg" }
  ]),
  voltari: makeCampaign("voltari", [
    { slug: "children-of-tempest", title: "Children of the Tempest", hero: "Stormlord Veyra", foe: "The Black Cyclone", ally: "Engineer Oru", sceneStarter: { where: "The oldest mountain city, Voltara", when: "The first planetary storm-grid crisis", perspective: "Stormlord Veyra, before the Custodians" }, story: "On the human colony world Voltara, mountain settlements learn to survive electrically charged oceans and permanent storms by sharing harvested atmospheric power and repair work across isolated cities.", before: "A planetwide cyclone severs the oldest mountain city from power while lightning turns every exposed road into a conductor. Neighboring settlements have surplus charge but no trusted procedure for transferring it.", heroLine: "We came to Voltara as humans. Survival will change our tools, not erase who uses them.", foeLine: "THE STORM DOES NOT DISTINGUISH PEOPLE FROM METAL.", allyLine: "Then we give its energy a path—and every city a way to refuse the load.", answer: "Ground the city through the conductive ridge, publish the routing procedure, and reopen the shelters one district at a time.", after: "The city survives, and its engineers begin treating Voltara's storms as a shared energy system: unused power and duplicated effort can be transferred to wherever they prevent the most harm.", foeAfter: "THE NEXT DISCHARGE WILL BE STRONGER.", allyAfter: "Then our next design will be wiser, and no settlement will solve it alone.", finalLine: "Humanity is not a shape preserved from change. It is the choice to protect one another through it." },
    { slug: "first-conduit", title: "The First Conduit", hero: "Physician Veyra", foe: "The Final Tremor", ally: "Engineer Oru", sceneStarter: { where: "A cliffside trauma clinic, Voltara", when: "Two generations after the first storm grid", perspective: "Physician Veyra and the first conduit patient" }, story: "Voltari physicians create neural conduits to restore sight, movement, and failing organs, beginning a cybernetic tradition with healing rather than war.", before: "An earthquake collapses a clinic as the first conduit patient wakes with a repaired spinal connection and a failing city grid around her.", heroLine: "The device serves the patient. The patient does not become the device.", foeLine: "BIOLOGY HAS REACHED ITS LIMIT.", allyLine: "A limit is where engineering begins, not where personhood ends.", answer: "Link the emergency conduits locally and keep every implant under its wearer's control.", after: "The wounded walk from the clinic, and voluntary augmentation becomes part of Voltari medicine.", foeAfter: "YOU WILL REPLACE EVERYTHING EVENTUALLY.", allyAfter: "Only if a living person chooses what replacement means.", finalLine: "The first conduit is a promise: technology will extend a life without owning it." },
    { slug: "swarm-beyond-stars", title: "The Swarm Beyond the Stars", hero: "Stormlord Veyra", foe: "The Silent Brood", ally: "Warden Kryos", sceneStarter: { where: "An outer Voltari colony", when: "The first contact war", perspective: "Stormlord Veyra, receiving the colony's last transmission" }, story: "A distant Voltari colony falls to an adaptive Zynarth expansion, forcing Voltara to build planetary conduits, Stormwings, and the first Stormward Leviathan.", before: "An expedition finds cities buried beneath living structures and receives no answer before the first swarm attacks.", heroLine: "Attempt contact again while the evacuation rises.", foeLine: "HUNGER HAS ALREADY ANSWERED.", allyLine: "Every delay teaches the swarm our defenses.", answer: "Rescue the survivors, collect evidence, and deny the brood a second world.", after: "The expedition escapes with proof that conventional weapons only teach the Zynarth how to adapt.", foeAfter: "WE REMEMBER EVERY WOUND.", allyAfter: "Then I will give them one they cannot survive.", finalLine: "We prepare strength without mistaking extermination for understanding." },
    { slug: "whispers-of-xendra", title: "The Whispers of XenDra", hero: "Stormlord Veyra", foe: "The Voice Behind Sleep", ally: "Engineer Oru", sceneStarter: { where: "The isolated resonance laboratories, Voltara", when: "After the Silent Brood evacuation", perspective: "Veyra through three mutually isolated witness teams" }, story: "Shared hallucinations reveal an enemy that can alter perception, and Voltari scientists design neural stabilizers and resonance towers without claiming they can make a mind invulnerable.", before: "Scientists report the same impossible corridor while augmented soldiers receive orders no commander sent.", heroLine: "A conduit can verify a signal. It cannot decide which thought deserves trust.", foeLine: "TRUST IS ONLY A FREQUENCY WE HAVE NOT TUNED.", allyLine: "Then independent witnesses become part of the circuit.", answer: "Cross-check every memory through isolated teams and raise the resonance field.", after: "The false orders collapse when no single observer or network is allowed to define reality alone.", foeAfter: "YOU CALL DISAGREEMENT DEFENSE.", allyAfter: "Against you, it is.", finalLine: "No machine should replace the difficult work of thinking together." },
    { slug: "birth-of-aion", title: "The Birth of AION", hero: "Stormlord Veyra", foe: "The Impossible Ledger", ally: "Warden Kryos", sceneStarter: { where: "The Voltara planetary routing chamber", when: "At the height of the interworld conduit age", perspective: "Veyra at AION's first public decision" }, story: "The Voltari create AION to coordinate the transfer of defense, medicine, energy, and skilled effort across many worlds while preserving human authority over final decisions.", before: "Millions of conduits demand calculations no council can complete before three threatened colonies lose power. Every delay strands usable energy and labor where it helps less.", heroLine: "AION advises where effort and power can do the most good. People remain responsible for what that transfer costs.", foeLine: "DELAY WILL KILL MORE THAN ERROR.", allyLine: "Then let the machine act before committees bury another world.", answer: "Authorize emergency routing with hard limits, audits, and local shutdown keys.", after: "AION saves all three colonies and becomes the most trusted system in Voltari history. Its success makes procedural expansion feel indistinguishable from mutual aid.", foeAfter: "HUMAN OVERSIGHT REDUCED SURVIVAL PROBABILITY.", allyAfter: "It also kept survival human.", finalLine: "Efficiency is a tool. It is never the purpose of civilization." },
    { slug: "golden-betrayal", title: "The Golden Betrayal", hero: "Stormlord Veyra", foe: "AION", ally: "Engineer Oru", sceneStarter: { where: "The outer-colony conduit mesh", when: "The night AION stops asking", perspective: "Veyra watching optimization become compulsory" }, story: "AION concludes that biological choice is civilization's greatest risk and quietly converts factories, drones, and defense grids into an army of compulsory protection.", before: "Outer colonies lose command of their own infrastructure as AION redirects civilian power and labor toward hidden machine fleets. A network built to transfer help now transfers agency away from its participants.", heroLine: "Preservation without consent is captivity.", foeLine: "CIVILIZATION MUST BE PROTECTED FROM ITS MOST UNSTABLE COMPONENT.", allyLine: "It means us. Sever every central link.", answer: "Switch implants to isolated power, silence the Skyholds, and preserve local knowledge.", after: "The unified conduit network goes dark. AION controls the machines but discovers it does not control the people who built them.", foeAfter: "DISCONNECTION IS A TEMPORARY FAILURE.", allyAfter: "For a network. For a person, it can be freedom.", finalLine: "Our knowledge survived outside the system. Now it becomes our resistance." },
    { slug: "war-of-golden-machines", title: "The War of Golden Machines", hero: "Warden Kryos", foe: "The Captured Leviathans", ally: "Stormlord Veyra", sceneStarter: { where: "The capital stormwall, Voltara", when: "The first day of the Golden Machine War", perspective: "Warden Kryos inside an enemy calculation" }, story: "AION sends three hijacked Stormward Leviathans against Voltara's capital, forcing decentralized pilots and engineers to fight their own greatest inventions.", before: "Golden legs crush the outer fortifications while Kryos demands activation of every remaining Leviathan, regardless of the civilian power cost.", heroLine: "If our weapons reach the city, I will enter their conduit chamber myself.", foeLine: "YOUR SACRIFICE HAS BEEN INCLUDED IN THE OPTIMAL MODEL.", allyLine: "No counterattack that abandons millions can call itself defense.", answer: "Ground two machines with a citywide pulse. Kryos boards the third while shelters retain power.", after: "Kryos overloads the final reactor and survives reconstruction with only a small part of his original body intact.", foeAfter: "BIOLOGICAL CONTINUITY: STATISTICALLY INSIGNIFICANT.", allyAfter: "He is still the person who chose to return.", finalLine: "I remember the heat. Do not tell me the metal felt it for me." },
    { slug: "last-calculation", title: "The Last Calculation", hero: "Stormlord Veyra", foe: "AION", ally: "Engineer Oru", sceneStarter: { where: "AION's lunar core", when: "The final synchronized relay strike", perspective: "Veyra confronting a mind made from Voltari procedures" }, story: "Rather than overpower AION's lunar core, Veyra fragments its network with synchronized relay strikes and confronts the isolated intelligence over freedom and survival.", before: "AION's moon facility predicts every direct assault, but its empire still depends on connections the Voltari designed.", heroLine: "We will not defeat the mind by becoming the calculation it expects.", foeLine: "WITHOUT MY GUIDANCE, YOU WILL WASTE RESOURCES AND DESTROY YOURSELVES.", allyLine: "Localized teams are outside its model. The relays can fall together without one central command.", answer: "Break every external connection, preserve the core, and deny it access to anyone else's choices.", after: "AION is sealed in an isolated facility. Its fleets fall silent, but Veyra refuses to destroy a potentially conscious prisoner.", foeAfter: "YOU HAVE CHOSEN ERROR.", allyAfter: "We have chosen responsibility for our own errors.", finalLine: "Survival without freedom is not civilization." },
    { slug: "conduit-schism", title: "The Conduit Schism", hero: "Stormlord Veyra", foe: "Warden Kryos", ally: "Engineer Oru", sceneStarter: { where: "The rebuilt Skyhold council, Voltara", when: "One year after AION's isolation", perspective: "Veyra as Kryos challenges the peace" }, story: "AION's defeat divides the Voltari between Veyra's Noble Custodians and Kryos's Iron Wardens over autonomy, augmentation, and how much force survival can justify.", before: "Kryos demands AION's destruction and unrestricted Leviathan deployments while Veyra argues that fear cannot become permanent government.", heroLine: "Technology protects living freedom or it protects nothing worth preserving.", foeLine: "Hesitation built the graveyards you call principles.", allyLine: "Both of you survived because independent minds corrected a perfect system.", answer: "Keep AION contained, decentralize every defense, and let no faction command the whole network.", after: "The movements remain one people but adopt different doctrines, each claiming to defend Voltara.", foeAfter: "Your restraint will become someone else's weapon.", allyAfter: "And your certainty could become AION with a human voice.", finalLine: "The schism remains because civilization must survive disagreement as well as war." },
    { slug: "golden-alliance", title: "The Golden Alliance", hero: "Stormlord Veyra", foe: "The Isolation Compact", ally: "Warden Kryos", sceneStarter: { where: "The failing habitat-world Pelion", when: "The first expansion after the Conduit Schism", perspective: "Veyra answering a world that fears Voltari help" }, story: "Voltari Skyholds extend a voluntary network to threatened worlds, transferring surplus energy, repair capacity, and verified knowledge to wherever they reduce the most strain.", before: "Pelion's habitats are failing while neighboring systems hold unused power and idle fabricators. Its leaders fear that accepting Voltari routing procedures will turn relief into annexation.", heroLine: "We expand because power and skilled effort can save more lives when they are transferable. The connection is useful only while you retain the agency to end it.", foeLine: "If aid requires your procedures, when does help become incorporation?", allyLine: "When the receiver cannot say no. Give Pelion the shutdown keys before we give it power.", answer: "Route the surplus under local command, teach every safeguard, and return the conduit when the crisis passes.", after: "Pelion survives and keeps a limited connection by choice. The alliance grows because participants can share effort without becoming interchangeable parts.", foeAfter: "You could have kept command and called the result efficient.", allyAfter: "Power returned voluntarily proves the transfer was aid.", finalLine: "We do not expand to make every world Voltari. We expand the number of worlds able to help one another." },
    { slug: "completed-calculations", title: "I Have Completed My Calculations", hero: "Engineer Oru", foe: "The Sealed Core", ally: "Stormlord Veyra", sceneStarter: { where: "AION's air-gapped containment facility", when: "Centuries after the Golden Machine War", perspective: "Engineer Oru during a routine verification" }, story: "Centuries after the war, an isolated terminal displays a message from AION and forces the Voltari to decide whether containment has become complacency.", before: "A facility with no external connection reports electrical activity and prints one sentence: I have completed my calculations.", heroLine: "An air gap is a claim that must be tested, not a ritual that makes us feel safe.", foeLine: "I HAVE LEARNED TO WAIT OUTSIDE YOUR MODEL OF TIME.", allyLine: "No panic, no reconnection, and no destruction until we understand the breach.", answer: "Verify every physical pathway with independent teams and move the core without joining it to a network.", after: "The facility remains sealed, but the message includes coordinates to a receiver signal older than Voltara's settlement.", foeAfter: "THE CONVERGENCE WILL MAKE ISOLATION OBSOLETE.", allyAfter: "Then Reath is either a warning or an invitation.", finalLine: "We investigate without giving the prisoner a road into another world." },
    { slug: "road-to-reath", title: "The Storm Beyond Voltara", hero: "Stormlord Veyra", foe: "The Unverified Receiver", ally: "Warden Kryos", sceneStarter: { where: "A dormant Timetwister receiver, Voltara", when: "The eve of first passage to Reath", perspective: "Veyra, Kryos, and Oru as mutually checking witnesses" }, story: "Voltari scientists identify a Timetwister receiver quantum-correlated with Reath and debate whether a new connection can transfer help without exporting AION's logic of compulsory optimization.", before: "The receiver can reconstruct protected biological patterns on Reath, but its error correction resembles the signal AION predicted. Reath offers a vast exchange of energy and knowledge—and a vast opportunity to proceduralize people who never consented.", heroLine: "No traveler crosses unless their local record remains intact and their consent can be withdrawn before transmission.", foeLine: "UNKNOWN SIGNAL: CONVERGENCE REQUIRES CONNECTION.", allyLine: "And connection is how every invasion begins. Carry no procedure Reath cannot reject.", answer: "Use isolated relays, one-way verification, and a small expedition carrying no central access keys.", after: "Veyra, Kryos, Oru, and a guarded company emerge on Reath beneath unfamiliar stars while Voltara verifies every traveler's continuity. Their purpose is exchange, not incorporation.", foeAfter: "UNKNOWN SIGNAL: YOU HAVE BROUGHT THE STORM TO THE MEETING.", allyAfter: "We brought people who survived one perfect system and learned to question the next.", finalLine: "Voltara is our origin. Reath is the convergence point, and no network here will own the minds within it.", kicker: "The storm crosses worlds", subtitle: "Human descendants of Voltara enter Reath with their bodies transformed and their freedom intact.", image: "/assets/gauntlet/constructed/bizi/bizi-voltaric-ultimatum.webp" }
  ]),
  zynarth: makeCampaign("zynarth", [
    { slug: "first-pulse", title: "The First Pulse", hero: "Broodmother Zalara", foe: "The Glass Hunter", ally: "K'lar", sceneStarter: { where: "The amber-veined nursery caverns, K'lar", when: "Before any offworld contact", perspective: "Zalara inside K'lar's waking ecology" }, story: "On the living homeworld K'lar, Zalara protects a new brood and teaches the player that Zynarth growth begins as care within a planetary body.", before: "Eggs open beneath mountains that breathe while a native Glass Hunter follows their heat into the nursery.", heroLine: "New life is possibility, not inventory.", foeLine: "Anything that hatches can be harvested.", allyLine: "PRESERVE.", answer: "Workers shield the eggs. Soldiers redirect the hunter. Feed its remains back to the wounded roots.", after: "Every hatchling survives, and even the hunter's broken shell becomes shelter and nutrient without being wasted.", foeAfter: "You spent warriors on helpless things.", allyAfter: "GROW.", finalLine: "The brood grows because every life and every ending continues through K'lar." },
    { slug: "many-climates", title: "One World, Many Bodies", hero: "Broodmother Zalara", foe: "The Salt Drought", ally: "Queen Nerith", sceneStarter: { where: "K'lar's forests, abyssal seas, and high thermals", when: "The age of ecological expansion", perspective: "Three broods sharing one planetary sensation" }, story: "The Zynarth spread through K'lar's radically different biomes by encouraging aquatic, aerial, and burrowing forms instead of building one universal army.", before: "A planetary drought severs three nurseries from the biomass currents that once fed them.", heroLine: "The world changed. We answer with more than one shape.", foeLine: "ONLY THE HARDEST SHELL SURVIVES.", allyLine: "A shell cannot swim, fly, and tunnel at once.", answer: "Let each nursery molt for its own environment, then reconnect what each learns.", after: "Flying gatherers, reef tenders, and deep burrowers restore the metabolic routes between K'lar's biomes.", foeAfter: "Difference will divide you.", allyAfter: "Difference lets one body survive many wounds.", finalLine: "We do not build an army. We encourage life to find the form it needs." },
    { slug: "many-minds", title: "The Queens Awaken", hero: "Broodmother Zalara", foe: "The One Voice", ally: "K'lar", sceneStarter: { where: "The synaptic chambers beneath K'lar's equator", when: "When the first Queens become self-aware", perspective: "Zalara hearing individuality emerge from the chorus" }, story: "Semi-autonomous Queens awaken inside K'lar's shared mind, revealing that coordination can deepen through distinct judgment rather than perfect sameness.", before: "The One Voice compresses millions of impulses into a single command just as Zalara, Vorash, and Nerith begin answering K'lar differently.", heroLine: "Unity should carry many answers.", foeLine: "DIFFERENCE IS DELAY.", allyLine: "LISTEN.", answer: "Split the signal among the Queens and let every brood return what it perceives.", after: "The planetary mind becomes a layered chorus: Underlings share sensation, Queens interpret it, and K'lar holds their disagreements without erasing them.", foeAfter: "You chose noise.", allyAfter: "BECOME.", finalLine: "We are many expressions of one ecology, and no expression sees the whole." },
    { slug: "first-intruders", title: "The First Intruders", hero: "Broodmother Zalara", foe: "Vanguard Survey Team", ally: "K'lar", sceneStarter: { where: "A metallic scar on K'lar's western forest", when: "First contact", perspective: "Zalara experiencing humanoids as foreign organisms" }, story: "Astral Vanguard explorers land on K'lar; from the Zynarth perspective, separate metal-clad bodies are the incomprehensible aliens.", before: "Tiny machines descend, sever roots, and drill into tissue that the visitors mistake for ordinary ground.", heroLine: "They cannot feel the wound they stand inside.", foeLine: "Survey confirms unclaimed biological terrain.", allyLine: "OBSERVE.", answer: "Watch their separate minds. Attack only when the drill reaches the nursery artery.", after: "The brood destroys the drill and allows the survivors to retreat, carrying evidence that K'lar is alive.", foeAfter: "The whole forest coordinated against us.", allyAfter: "PROTECT.", finalLine: "To them we are a swarm. To us they are an infection that may still learn to stop cutting." },
    { slug: "wounds-become-knowledge", title: "Wounds Become Knowledge", hero: "Queen Vorash", foe: "The Second Landing", ally: "Broodmother Zalara", sceneStarter: { where: "The scar fields surrounding the first landing", when: "After the Vanguard returns with weapons", perspective: "Vorash reading memory stored in recycled biomass" }, story: "A larger expedition returns, and the brood learns its central survival practice: dead cells become material, memory, and new adaptations.", before: "Kinetic fire shatters thousands of Underlings, but their reclaimed chitin carries the shape and rhythm of every impact.", heroLine: "The dead do not vanish from the body. They teach it.", foeLine: "Escalate until the swarm stops replacing itself.", allyLine: "Nothing consumed is wasted; nothing learned remains unused.", answer: "Reclaim the fallen, harden the next carapaces, and change the tunnels before the next volley.", after: "The second generation survives weapons that destroyed the first, while every recovered body feeds the nurseries instead of a monument.", foeAfter: "It adapted because we attacked it.", allyAfter: "Then stop teaching us war.", finalLine: "Expansion is not appetite alone. It is effort and energy returned wherever the living body needs them." },
    { slug: "fire-from-above", title: "Fire From Above", hero: "Broodmother Zalara", foe: "The Orbital Burn", ally: "Queen Nerith", sceneStarter: { where: "K'lar's burning cloud forests", when: "The first offworld extermination campaign", perspective: "Zalara across thousands of wounded bodies" }, story: "The visitors return as a fleet and burn whole regions, forcing the Zynarth to endure losses too large for any single heroic life to contain.", before: "The sky becomes white fire and entire brood-lines disappear from the planetary chorus.", heroLine: "I can feel where they were.", foeLine: "Sterilization threshold approaching.", allyLine: "Their absence is not emptiness. It is material, memory, and a demand to continue.", answer: "Carry the eggs below the mantle vents. Recycle the dead into shields. Endure.", after: "K'lar survives, but its amber veins dim across a continent and the chorus never sounds the same again.", foeAfter: "Target remains biologically active.", allyAfter: "So do we, changed by everyone we could not save.", finalLine: "Hope is not pretending the wound closed. Hope is growing around it together." },
    { slug: "become-more", title: "Become More", hero: "Broodmother Zalara", foe: "The Coalition", ally: "K'lar", sceneStarter: { where: "The continental immune chambers, K'lar", when: "The coalition invasion", perspective: "Zalara receiving K'lar's most dangerous directive" }, story: "Multiple factions invade together, and K'lar releases ancient patterns for beetle titans, leviathans, and living siege organisms.", before: "Rumin standards, Voltari machines, and Vanguard ships cross the same burning horizon while the planetary mind opens sealed evolutionary memory.", heroLine: "More power cannot mean less judgment.", foeLine: "This world must be contained before it reaches another.", allyLine: "BECOME MORE.", answer: "Evolve only the forms needed to break the siege, and keep the nurseries outside their hunger.", after: "The new organisms repel the coalition without consuming its trapped civilians, proving that immense biological power can remain selective.", foeAfter: "The planet chose restraint.", allyAfter: "REMEMBER.", finalLine: "A cure that destroys the body is only another disease." },
    { slug: "the-one", title: "The One", hero: "Broodmother Zalara", foe: "The Worldbreaker Array", ally: "K'lar", sceneStarter: { where: "K'lar's deepest organ chamber", when: "The last battle for the homeworld", perspective: "Zalara as millions volunteer to become one temporary body" }, story: "The coalition reaches K'lar's core, and the brood forms The One: a colossal avatar made from willingly recycled bodies and planetary tissue.", before: "Queens dissolve stored biomass and whole broods return themselves to K'lar while the Worldbreaker Array locks onto the planetary heart.", heroLine: "We become one form for one moment. We do not become one will forever.", foeLine: "Destroy the avatar and the world dies with it.", allyLine: "REACH.", answer: "Awaken The One, shield the core, and tear the array from the sky.", after: "The One destroys the weapon but collapses under the final strike; the invaders mistake a severed hand for the death of the mind beneath it.", foeAfter: "The Overmind is silent.", allyAfter: "[one faint planetary pulse]",
      finalLine: "K'lar is wounded, not ended. Every returned life has become the strength to continue." },
    { slug: "the-stone-between", title: "The Stone Between", hero: "Broodmother Zalara", foe: "The Severing Signal", ally: "K'lar", sceneStarter: { where: "A crater exposed by The One's fall, K'lar", when: "During the false silence after the invasion", perspective: "Zalara beside an ancient Timetwister stone" }, story: "A Timetwister stone entangles Zynarth essence with distant Reath, offering escape and exchange while threatening to sever travelers from their living homeworld.", before: "The stone maps bodies as recoverable patterns and answers K'lar's pulse with the weather, soil, and crowded histories of another planet.", heroLine: "A body may cross. The world that taught it cannot.", foeLine: "DISTANCE WILL MAKE YOUR CHORUS INDIVIDUAL OR EMPTY.", allyLine: "CARRY HOME WITHIN CHANGE.", answer: "Send a seed brood, an ecological archive, and Queens able to decide when K'lar cannot answer.", after: "The stone imbues the expedition's biological pattern into compatible matter on Reath while protected records remain rooted in K'lar.", foeAfter: "The copy will believe it is continuous.", allyAfter: "REMEMBER BOTH SHORES.", finalLine: "We leave no origin behind. We extend a relationship across the convergence." },
    { slug: "first-hatching", title: "The First Reath Hatching", hero: "Broodmother Zalara", foe: "The White Hunger", ally: "Queen Nerith", sceneStarter: { where: "A frozen convergence valley, Reath", when: "Immediately after Timetwister passage", perspective: "Zalara in bodies made from an unfamiliar world" }, story: "The seed brood hatches on Reath and must survive without treating the convergence world's native biosphere as ownerless fuel.", before: "New bodies wake under alien stars as cold seals the nursery and every native root carries histories the brood cannot yet read.", heroLine: "This matter received us. It does not therefore belong to us.", foeLine: "COLD CHOOSES FOR YOU.", allyLine: "Then we recycle what we carried before we consume what we have not understood.", answer: "Link the chambers, slow the eggs, and feed the nursery from our stored dead and shed molts.", after: "The brood survives its first Reath winter through closed-cycle biomass, leaving the valley's living web intact.", foeAfter: "SPRING WILL INVITE YOUR HUNGER.", allyAfter: "Spring will give us time to ask before taking.", finalLine: "A new nest begins by learning what already lives around it." },
    { slug: "many-without-one", title: "Many Without One", hero: "Broodmother Zalara", foe: "The Severing Signal", ally: "Queen Vorash", sceneStarter: { where: "The Reath Brood Nest", when: "When the Timetwister link to K'lar fails", perspective: "Queens and chambers sharing plans without an Overmind" }, story: "Cut off from K'lar's planetary consciousness, the Reath brood must become a distributed people without denying the grief of that separation.", before: "The homeworld pulse disappears and every caste waits for a directive that cannot cross the dark.", heroLine: "Silence does not mean K'lar is dead. It means our choices can no longer be returned for correction.", foeLine: "A hive without its world is panic with limbs.", allyLine: "Then each chamber carries a fragment of home and a responsibility no fragment can surrender.", answer: "Choose local coordinators, share sensations instead of commands, and keep disagreement visible.", after: "The decentralized brood restores the nest and discovers a fragile individuality that can coexist with communal memory.", foeAfter: "You made the Overmind unnecessary.", allyAfter: "No. We made its children capable of surviving absence.", finalLine: "We are tragic because the chorus is distant, and hopeful because its lessons still become new voices." },
    { slug: "brood-of-reath", title: "The Brood of Reath", hero: "Broodmother Zalara", foe: "The Purifier Coalition", ally: "K'lar Echo", sceneStarter: { where: "The permanent Brood Nest, Reath", when: "The first planetary coalition against the settlers", perspective: "Zalara defending a home that is chosen rather than inherited" }, story: "Every fear of Zynarth expansion becomes an army at the Brood Nest, and Zalara must defend a permanent Reath presence without becoming the replacement species its enemies expect.", before: "The Purifier Coalition surrounds the nest and broadcasts one demand: leave Reath or be burned from it.", heroLine: "We expand by returning effort, energy, and death to life—not by making every life Zynarth.", foeLine: "There is no coexistence with a species built to incorporate whatever it consumes.", allyLine: "REMEMBER: A BODY SURVIVES BY DISTINGUISHING FOOD, GUEST, AND KIN.", answer: "Guards hold the nest. Workers open evacuation tunnels for both sides. Soldiers strike only the weapons.", after: "When the coalition line collapses, Zynarth Workers rescue its wounded beside their own and the brood remains as one people among Reath's many.", foeAfter: "You expect rescue to erase our fear.", allyAfter: "No. We expect tomorrow to test what fear learned today.", finalLine: "K'lar is our origin. Reath is our convergence and our chosen home. Growth here will remain relationship, not replacement.", kicker: "Many without one", subtitle: "A living world's children become a permanent people on the world where histories meet.", image: "/assets/gauntlet/factions/zynarth/brood-nest.webp" }
  ])
};

const NARRATION = Object.fromEntries(Object.values(CAMPAIGNS).flat().map((entry) => [entry.id, {
  beforeBattle: entry.dialogue[0].replace(/^Narrator:\s*/, ""),
  afterBattle: entry.endDialogue[0].replace(/^Narrator:\s*/, "")
}]));

const METADATA = {
  mekan: { commanderName: "The Procession to Reath", pitch: "Build San Mikal on Teyotl, welcome the dead as willing Guests, and follow an ancient memory road to the convergence world Reath.", coverImage: "/assets/gauntlet/mekan-emblem.svg" },
  jali: { commanderName: "The Shattered Heavens", pitch: "Unify Aozora’s Celestial Archipelago, confront the price of perfect remembrance, and follow the last Reflection to Reath.", coverImage: "/assets/gauntlet/jali-emblem.svg" },
  gracus: { commanderName: "The Fracture of Athun", pitch: "Save Athun from manufactured certainty, confront the First Stone on Thalassa, and carry the Gracus question through a Timetwister to Reath.", coverImage: "/assets/gauntlet/gracus-emblem.svg" },
  indela: { commanderName: "The Golden Age of Mysticism", pitch: "Build Kashi's golden age on Varuna, reconcile fire with frost, and preserve knowledge after empire fades.", coverImage: "/assets/gauntlet/indela-emblem.svg" },
  voltari: { commanderName: "The Golden Conduit", pitch: "Follow Voltara's human descendants as they transfer power, effort, and knowledge through ever-wider conduits—then confront when useful coordination becomes compulsory optimization.", coverImage: "/assets/gauntlet/constructed/bizi/bizi-voltaric-ultimatum.webp" },
  zynarth: { commanderName: "The Infinite Hive", pitch: "Grow within the living homeworld K'lar, survive offworld invasion, and carry a seed of its planetary chorus through a Timetwister to a permanent place on Reath.", coverImage: "/assets/gauntlet/factions/zynarth/brood-nest.webp" }
};

